const body = $input.first().json.body || $input.first().json;
let lotId = (body.lot_id || '').trim();
let machineId = (body.machine_id || '').trim();
lotId = lotId.replace(/[^A-Za-z0-9_-]/g, '');
machineId = machineId.replace(/[^A-Za-z0-9_-]/g, '');
return { json: { lot_id: lotId, machine_id: machineId } };

const rows = $input.first().json || [];
const arr = Array.isArray(rows) ? rows : [rows];
const count = arr.length;
let text = '';
if (count === 0) {
  text = '未找到Lot记录';
} else {
  text = arr.map((r, i) => `${i+1}. Lot: ${r.lot_id || ''} 机台: ${r.machine_id || ''} 状态: ${r.status || ''} 晶圆: ${r.wafer_qty || 0}`).join('\n');
}
return { json: { lots: arr, count: count, summary: text } };
